import "./Registrar_Empresa.css";
import { useState } from "react";

const RegistrarEmpresa = ({ setView }) => {
  const [formData, setFormData] = useState({
    contactName: "",
    email: "",
    comments: ""
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // Aquí puedes agregar la lógica para manejar el envío del formulario
    console.log(formData);
  };

  return (
    <div className="registrar-empresa-container">
      <h2>Registrar Empresa</h2>
      <form className="contact-form" onSubmit={handleSubmit}>
        <div className="form-group">
          <label htmlFor="contact-name">Name</label>
          <div className="input-group">
            <div className="input-group-prepend">
              <span className="input-group-text"><i className="bi bi-person"></i></span>
            </div>
            <input
              id="contact-name"
              name="contactName"
              placeholder="Your name"
              className="form-control"
              value={formData.contactName}
              onChange={handleChange}
              required
            />
          </div>
        </div>
        <div className="form-group">
          <label htmlFor="contact-mail">Email</label>
          <div className="input-group">
            <div className="input-group-prepend">
              <span className="input-group-text"><i className="bi bi-envelope"></i></span>
            </div>
            <input
              id="contact-mail"
              name="email"
              placeholder="Your email"
              type="email"
              className="form-control"
              value={formData.email}
              onChange={handleChange}
              required
            />
          </div>
        </div>
        <div className="form-group">
          <label htmlFor="contact-message">Message</label>
          <div className="input-group">
            <div className="input-group-prepend">
              <span className="input-group-text"><i className="bi bi-chat-dots"></i></span>
            </div>
            <textarea
              id="contact-message"
              name="comments"
              placeholder="Your message"
              className="form-control"
              rows="6"
              value={formData.comments}
              onChange={handleChange}
              required
            />
          </div>
        </div>
        <button type="submit" className="btn btn-info btn-block">
          <i className="bi bi-cursor-fill"></i> Send Message
        </button>
      </form>
      <div className="btn-regresar" onClick={() => setView("login")}>Regresar</div>
    </div>
  );
};

export default RegistrarEmpresa;
